# The ten compound-unit characters of the Big5 符號 plane (codes inside
# charsetRange['big5S'] = [0xA140, 0xA3C0)): the branch files each in the
# big5S dict and must answer "big5S".
BIG5S_CHARACTERS = "兙兛兝兞兡兣卄嗧瓩糎"


class GetCharSetTierTests(unittest.TestCase):
    def check(self, root, answered, dict_attr, counter):
        app = MODULE.CinToJson()
        result = app.getCharSet("k", root)
        self.assertEqual(answered, result,
                         "getCharSet(%r) answered %r but %r is the tier that "
                         "gained the root" % (root, result, dict_attr))
        self.assertEqual([root], getattr(app, dict_attr)["k"])
        self.assertEqual(1, app.cincount[counter])
        for attr in TIER_DICT_ATTRS:
            if attr != dict_attr:
                self.assertEqual({}, getattr(app, attr),
                                 "%s stayed outside the one-tier rule" % attr)

    def test_every_tier_answers_the_dict_it_fills(self):
        for label, root, answered, dict_attr, counter in TIER_CASES:
            with self.subTest(label):
                self.check(root, answered, dict_attr, counter)

    def test_big5_symbol_characters_answer_big5S(self):
        for char in BIG5S_CHARACTERS:
            with self.subTest(char):
                self.check(char, "big5S", "big5S", "big5S")

    def test_big5Other_is_left_empty_by_the_encodable_ideographs(self):
        """The one ladder branch with no single-char representative: no CJK
        Unified ideograph the bundled codec can encode carries a big5 code
        outside the three populated planes, so big5Other stays empty across the
        whole block. The bounds are the ladder's own, taken from a fresh
        instance."""
        bounds = MODULE.CinToJson().charsetRange
        app = MODULE.CinToJson()
        for codepoint in range(bounds['cjk'][0], bounds['cjk'][1]):
            app.getCharSet("k", chr(codepoint))
        self.assertEqual({}, app.big5Other)


